50: /**
51:  * A base load balancing policy for those policies which has multiple children such as
52:  * ClusterManager or the petiole policies.  For internal use only.
53:  */
54: @Internal
55: public abstract class MultiChildLoadBalancer extends LoadBalancer {
56: 
57:   private static final Logger logger = Logger.getLogger(MultiChildLoadBalancer.class.getName());
58:   private final Map<Object, ChildLbState> childLbStates = new LinkedHashMap<>();
59:   private final Helper helper;
60:   // Set to true if currently in the process of handling resolved addresses.
61:   protected boolean resolvingAddresses;
62: 
63:   protected final LoadBalancerProvider pickFirstLbProvider = new PickFirstLoadBalancerProvider();
64: 
65:   protected ConnectivityState currentConnectivityState;
66: 
67:   protected MultiChildLoadBalancer(Helper helper) {
68:     this.helper = checkNotNull(helper, "helper");
69:     logger.log(Level.FINE, "Created");
70:   }
71: 
72:   protected abstract SubchannelPicker getSubchannelPicker(
73:       Map<Object, SubchannelPicker> childPickers);
74: 
75:   protected SubchannelPicker getInitialPicker() {
76:     return EMPTY_PICKER;
77:   }
78: 
79:   protected SubchannelPicker getErrorPicker(Status error)  {
80:     return new FixedResultPicker(PickResult.withError(error));
81:   }
82: 
83:   /**
84:    * Generally, the only reason to override this is to expose it to a test of a LB in a different
85:    * package.
86:    */
87:   protected ImmutableMap<Object, ChildLbState> getImmutableChildMap() {
88:     return ImmutableMap.copyOf(childLbStates);
89:   }
90: 
91:   @VisibleForTesting
92:   protected Collection<ChildLbState> getChildLbStates() {
93:     return childLbStates.values();
94:   }
95: 
96:   /**
97:    * Generally, the only reason to override this is to expose it to a test of a LB in a
98:    * different package.
99:    */
100:   protected ChildLbState getChildLbState(Object key) {
101:     if (key == null) {
102:       return null;
103:     }
104:     if (key instanceof EquivalentAddressGroup) {
105:       key = new Endpoint((EquivalentAddressGroup) key);
106:     }
107:     return childLbStates.get(key);
108:   }
109: 
110:   /**
111:    * Generally, the only reason to override this is to expose it to a test of a LB in a different
112:    * package.
113:    */
114:   protected ChildLbState getChildLbStateEag(EquivalentAddressGroup eag) {
115:     return getChildLbState(new Endpoint(eag));
116:   }
117: 
118:   /**
119:    * Override to utilize parsing of the policy configuration or alternative helper/lb generation.
120:    */
121:   protected Map<Object, ChildLbState> createChildLbMap(ResolvedAddresses resolvedAddresses) {
122:     Map<Object, ChildLbState> childLbMap = new HashMap<>();
123:     List<EquivalentAddressGroup> addresses = resolvedAddresses.getAddresses();
124:     for (EquivalentAddressGroup eag : addresses) {
125:       Endpoint endpoint = new Endpoint(eag); // keys need to be just addresses
126:       ChildLbState existingChildLbState = childLbStates.get(endpoint);
127:       if (existingChildLbState != null) {
128:         childLbMap.put(endpoint, existingChildLbState);
129:       } else {
130:         childLbMap.put(endpoint, createChildLbState(endpoint, null, getInitialPicker()));
131:       }
132:     }
133:     return childLbMap;
134:   }
135: 
136:   /**
137:    * Override to create an instance of a subclass.
138:    */
139:   protected ChildLbState createChildLbState(Object key, Object policyConfig,
140:       SubchannelPicker initialPicker) {
141:     return new ChildLbState(key, pickFirstLbProvider, policyConfig, initialPicker);
142:   }
143: 
144:   /**
145:    *   Override to completely replace the default logic or to do additional activities.
146:    */
147:   @Override
148:   public boolean acceptResolvedAddresses(ResolvedAddresses resolvedAddresses) {
149:     try {
150:       resolvingAddresses = true;
151: 
152:       // process resolvedAddresses to update children
153:       AcceptResolvedAddressRetVal acceptRetVal =
154:           acceptResolvedAddressesInternal(resolvedAddresses);
155:       if (!acceptRetVal.valid) {
156:         return false;
157:       }
158: 
159:       // Update the picker and
160:       updateOverallBalancingState();
161: 
162:       // shutdown removed children
163:       shutdownRemoved(acceptRetVal.removedChildren);
164:       return true;
165:     } finally {
166:       resolvingAddresses = false;
167:     }
168:   }
169: 
170:   /**
171:    * Override this if your keys are not of type Endpoint.
172:    * @param key Key to identify the ChildLbState
173:    * @param resolvedAddresses list of addresses which include attributes
174:    * @param childConfig a load balancing policy config. This field is optional.
175:    * @return a fully loaded ResolvedAddresses object for the specified key
176:    */
177:   protected ResolvedAddresses getChildAddresses(Object key, ResolvedAddresses resolvedAddresses,
178:       Object childConfig) {
179:     Endpoint endpointKey;
180:     if (key instanceof EquivalentAddressGroup) {
181:       endpointKey = new Endpoint((EquivalentAddressGroup) key);
182:     } else {
183:       checkArgument(key instanceof Endpoint, "key is wrong type");
184:       endpointKey = (Endpoint) key;
185:     }
186: 
187:     // Retrieve the non-stripped version
188:     EquivalentAddressGroup eagToUse = null;
189:     for (EquivalentAddressGroup currEag : resolvedAddresses.getAddresses()) {
190:       if (endpointKey.equals(new Endpoint(currEag))) {
191:         eagToUse = currEag;
192:         break;
193:       }
194:     }
195: 
196:     checkNotNull(eagToUse, key + " no longer present in load balancer children");
197: 
198:     return resolvedAddresses.toBuilder()
199:         .setAddresses(Collections.singletonList(eagToUse))
200:         .setLoadBalancingPolicyConfig(childConfig)
201:         .build();
202:   }
203: 
204:   /**
205:    *   This does the work to update the child map and calculate which children have been removed.
206:    *   You must call {@link #updateOverallBalancingState} to update the picker
207:    *   and call {@link #shutdownRemoved(List)} to shutdown the endpoints that have been removed.
208:     */
209:   protected AcceptResolvedAddressRetVal acceptResolvedAddressesInternal(
210:       ResolvedAddresses resolvedAddresses) {
211:     logger.log(Level.FINE, "Received resolution result: {0}", resolvedAddresses);
212:     Map<Object, ChildLbState> newChildren = createChildLbMap(resolvedAddresses);
213: 
214:     if (newChildren.isEmpty()) {
215:       handleNameResolutionError(Status.UNAVAILABLE.withDescription(
216:           "NameResolver returned no usable address. " + resolvedAddresses));
217:       return new AcceptResolvedAddressRetVal(false, null);
218:     }
219: 
220:     // Do adds and updates
221:     for (Map.Entry<Object, ChildLbState> entry : newChildren.entrySet()) {
222:       final Object key = entry.getKey();
223:       LoadBalancerProvider childPolicyProvider = entry.getValue().getPolicyProvider();
224:       Object childConfig = entry.getValue().getConfig();
225:       if (!childLbStates.containsKey(key)) {
226:         childLbStates.put(key, entry.getValue());
227:       } else {
228:         // Reuse the existing one
229:         ChildLbState existingChildLbState = childLbStates.get(key);
230:         if (existingChildLbState.isDeactivated() && reactivateChildOnReuse()) {
231:           existingChildLbState.reactivate(childPolicyProvider);
232:         }
233:       }
234: 
235:       ChildLbState childLbState = childLbStates.get(key);
236:       ResolvedAddresses childAddresses = getChildAddresses(key, resolvedAddresses, childConfig);
237:       childLbStates.get(key).setResolvedAddresses(childAddresses); // update child
238:       if (!childLbState.deactivated) {
239:         childLbState.lb.handleResolvedAddresses(childAddresses); // update child LB
240:       }
241:     }
242: 
243:     List<ChildLbState> removedChildren = new ArrayList<>();
244:     // Do removals
245:     for (Object key : ImmutableList.copyOf(childLbStates.keySet())) {
246:       if (!newChildren.containsKey(key)) {
247:         ChildLbState childLbState = childLbStates.get(key);
248:         childLbState.deactivate();
249:         removedChildren.add(childLbState);
250:       }
251:     }
252: 
253:     return new AcceptResolvedAddressRetVal(true, removedChildren);
254:   }
255: 
256:   protected void shutdownRemoved(List<ChildLbState> removedChildren) {
257:     // Do shutdowns after updating picker to reduce the chance of failing an RPC by picking a
258:     // subchannel that has been shutdown.
259:     for (ChildLbState childLbState : removedChildren) {
260:       childLbState.shutdown();

260:       childLbState.shutdown();
261:     }
262:   }
263: 
264:   @Override
265:   public void handleNameResolutionError(Status error) {
266:     if (currentConnectivityState != READY)  {
267:       helper.updateBalancingState(TRANSIENT_FAILURE, getErrorPicker(error));
268:     }
269:   }
270: 
271:   protected void handleNameResolutionError(ChildLbState child, Status error) {
272:     child.lb.handleNameResolutionError(error);
273:   }
274: 
275:   /**
276:    * If true, then when a subchannel state changes to idle, the corresponding child will
277:    * have requestConnection called on its LB.  Also causes the PickFirstLB to be created when
278:    * the child is created or reused.
279:    */
280:   protected boolean reconnectOnIdle() {
281:     return true;
282:   }
283: 
284:   /**
285:    * If true, then when {@link #acceptResolvedAddresses} sees a key that was already part of the
286:    * child map which is deactivated, it will call reactivate on the child.
287:    * If false, it will leave it deactivated.
288:    */
289:   protected boolean reactivateChildOnReuse() {
290:     return true;
291:   }
292: 
293:   @Override
294:   public void shutdown() {
295:     logger.log(Level.INFO, "Shutdown");
296:     for (ChildLbState state : childLbStates.values()) {
297:       state.shutdown();
298:     }
299:     childLbStates.clear();
300:   }
301: 
302:   protected void updateOverallBalancingState() {
303:     ConnectivityState overallState = null;
304:     final Map<Object, SubchannelPicker> childPickers = new HashMap<>();
305:     for (ChildLbState childLbState : getChildLbStates()) {
306:       if (childLbState.deactivated) {
307:         continue;
308:       }
309:       childPickers.put(childLbState.key, childLbState.currentPicker);
310:       overallState = aggregateState(overallState, childLbState.currentState);
311:     }
312: 
313:     if (overallState != null) {
314:       helper.updateBalancingState(overallState, getSubchannelPicker(childPickers));
315:       currentConnectivityState = overallState;
316:     }
317:   }
318: 
319:   @Nullable
320:   protected static ConnectivityState aggregateState(
321:       @Nullable ConnectivityState overallState, ConnectivityState childState) {
322:     if (overallState == null) {
323:       return childState;
324:     }
325:     if (overallState == READY || childState == READY) {
326:       return READY;
327:     }
328:     if (overallState == CONNECTING || childState == CONNECTING) {
329:       return CONNECTING;
330:     }
331:     if (overallState == IDLE || childState == IDLE) {
332:       return IDLE;
333:     }
334:     return overallState;
335:   }
336: 
337:   protected Helper getHelper() {
338:     return helper;
339:   }
340: 
341:   protected void removeChild(Object key) {
342:     childLbStates.remove(key);
343:   }
344: 
345:   /**
346:    * Filters out non-ready and deactivated child load balancers (subchannels).
347:    */
348:   protected List<ChildLbState> getReadyChildren() {
349:     List<ChildLbState> activeChildren = new ArrayList<>();
350:     for (ChildLbState child : getChildLbStates()) {
351:       if (!child.isDeactivated() && child.getCurrentState() == READY) {
352:         activeChildren.add(child);
353:       }
354:     }
355:     return activeChildren;
356:   }
357: 
358:   /**
359:    * This represents the state of load balancer children.  Each endpoint (represented by an
360:    * EquivalentAddressGroup or EDS string) will have a separate ChildLbState which in turn will
361:    * define a GracefulSwitchLoadBalancer.  When the GracefulSwitchLoadBalancer is activated, a
362:    * single PickFirstLoadBalancer will be created which will then create a subchannel and start
363:    * trying to connect to it.
364:    *
365:    * <p>A ChildLbStateHelper is the glue between ChildLbState and the helpers associated with the
366:    * petiole policy above and the PickFirstLoadBalancer's helper below.
367:    *
368:    * <p>If you wish to store additional state information related to each subchannel, then extend
369:    * this class.
370:    */
371:   public class ChildLbState {
372:     private final Object key;
373:     private ResolvedAddresses resolvedAddresses;
374:     private final Object config;
375: 
376:     private final GracefulSwitchLoadBalancer lb;
377:     private final LoadBalancerProvider policyProvider;
378:     private ConnectivityState currentState;
379:     private SubchannelPicker currentPicker;
380:     private boolean deactivated;
381: 
382:     public ChildLbState(Object key, LoadBalancerProvider policyProvider, Object childConfig,
383:         SubchannelPicker initialPicker) {
384:       this(key, policyProvider, childConfig, initialPicker, null, false);
385:     }
386: 
387:     public ChildLbState(Object key, LoadBalancerProvider policyProvider, Object childConfig,
388:           SubchannelPicker initialPicker, ResolvedAddresses resolvedAddrs, boolean deactivated) {
389:       this.key = key;
390:       this.policyProvider = policyProvider;
391:       this.deactivated = deactivated;
392:       this.currentPicker = initialPicker;
393:       this.config = childConfig;
394:       this.lb = new GracefulSwitchLoadBalancer(new ChildLbStateHelper());
395:       this.currentState = deactivated ? IDLE : CONNECTING;
396:       this.resolvedAddresses = resolvedAddrs;
397:       if (!deactivated) {
398:         lb.switchTo(policyProvider);
399:       }
400:     }
401: 
402:     @Override
403:     public String toString() {
404:       return "Address = " + key
405:           + ", state = " + currentState
406:           + ", picker type: " + currentPicker.getClass()
407:           + ", lb: " + lb.delegate().getClass()
408:           + (deactivated ? ", deactivated" : "");
409:     }
410: 
411:     public Object getKey() {
412:       return key;
413:     }
414: 
415:     Object getConfig() {
416:       return config;
417:     }
418: 
419:     protected GracefulSwitchLoadBalancer getLb() {
420:       return lb;
421:     }
422: 
423:     public LoadBalancerProvider getPolicyProvider() {
424:       return policyProvider;
425:     }
426: 
427:     protected Subchannel getSubchannels(PickSubchannelArgs args) {
428:       if (getCurrentPicker() == null) {
429:         return null;
430:       }
431:       return getCurrentPicker().pickSubchannel(args).getSubchannel();
432:     }
433: 
434:     public ConnectivityState getCurrentState() {
435:       return currentState;
436:     }
437: 
438:     public SubchannelPicker getCurrentPicker() {
439:       return currentPicker;
440:     }
441: 
442:     public EquivalentAddressGroup getEag() {
443:       if (resolvedAddresses == null || resolvedAddresses.getAddresses().isEmpty()) {
444:         return null;
445:       }
446:       return resolvedAddresses.getAddresses().get(0);
447:     }
448: 
449:     public boolean isDeactivated() {
450:       return deactivated;
451:     }
452: 
453:     protected void setDeactivated() {
454:       deactivated = true;
455:     }
456: 
457:     protected void markReactivated() {
458:       deactivated = false;
459:     }
460: 
461:     protected void setResolvedAddresses(ResolvedAddresses newAddresses) {
462:       checkNotNull(newAddresses, "Missing address list for child");
463:       resolvedAddresses = newAddresses;
464:     }
465: 
466:     /**
467:      * The default implementation. This not only marks the lb policy as not active, it also removes
468:      * this child from the map of children maintained by the petiole policy.
469:      *
470:      * <p>Note that this does not explicitly shutdown this child.  That will generally be done by
471:      * acceptResolvedAddresses on the LB, but can also be handled by an override such as is done
472:      * in <a href=" https://github.com/grpc/grpc-java/blob/master/xds/src/main/java/io/grpc/xds/ClusterManagerLoadBalancer.java">ClusterManagerLoadBalancer</a>.
473:      *
474:      * <p>If you plan to reactivate, you will probably want to override this to not call
475:      * childLbStates.remove() and handle that cleanup another way.
476:      */
477:     protected void deactivate() {
478:       if (deactivated) {
479:         return;
480:       }
481: 
482:       childLbStates.remove(key); // This means it can't be reactivated again
483:       deactivated = true;
484:       logger.log(Level.FINE, "Child balancer {0} deactivated", key);
485:     }
486: 
487:     /**
488:      * This base implementation does nothing but reset the flag.  If you really want to both
489:      * deactivate and reactivate you should override them both.
490:      */
491:     protected void reactivate(LoadBalancerProvider policyProvider) {
492:       deactivated = false;
493:     }
494: 
495:     protected void shutdown() {
496:       lb.shutdown();
497:       this.currentState = SHUTDOWN;
498:       logger.log(Level.FINE, "Child balancer {0} deleted", key);
499:     }
500: 
501:     /**
502:      * ChildLbStateHelper is the glue between ChildLbState and the helpers associated with the
503:      * petiole policy above and the PickFirstLoadBalancer's helper below.
504:      *
505:      * <p>The ChildLbState updates happen during updateBalancingState.  Otherwise, it is doing
506:      * simple forwarding.
507:      */
508:     protected ResolvedAddresses getResolvedAddresses() {
509:       return resolvedAddresses;
510:     }
511: 
512:     private final class ChildLbStateHelper extends ForwardingLoadBalancerHelper {
513: 
514:       @Override
515:       public void updateBalancingState(final ConnectivityState newState,
516:           final SubchannelPicker newPicker) {
517:         // If we are already in the process of resolving addresses, the overall balancing state
518:         // will be updated at the end of it, and we don't need to trigger that update here.
519:         if (!childLbStates.containsKey(key)) {
520:           return;
521:         }
522:         // Subchannel picker and state are saved, but will only be propagated to the channel
523:         // when the child instance exits deactivated state.
524:         currentState = newState;
525:         currentPicker = newPicker;
526:         if (!deactivated && !resolvingAddresses) {
527:           if (newState == IDLE && reconnectOnIdle()) {
528:             lb.requestConnection();
529:           }
530:           updateOverallBalancingState();
531:         }
532:       }
533: 
534:       @Override
535:       protected Helper delegate() {
536:         return helper;
537:       }
538:     }
539:   }
540: 
541:   /**
542:    * Endpoint is an optimization to quickly lookup and compare EquivalentAddressGroup address sets.
543:    * Ignores the attributes, orders the addresses in a deterministic manner and converts each
544:    * address into a string for easy comparison.  Also caches the hashcode.
545:    * Is used as a key for ChildLbState for most load balancers (ClusterManagerLB uses a String).
546:    */
547:   protected static class Endpoint {
548:     final String[] addrs;
549:     final int hashCode;
550: 
551:     public Endpoint(EquivalentAddressGroup eag) {
552:       checkNotNull(eag, "eag");
553: 
554:       addrs = new String[eag.getAddresses().size()];
555:       int i = 0;
556:       for (SocketAddress address : eag.getAddresses()) {
557:         addrs[i] = address.toString();
558:       }
559:       Arrays.sort(addrs);
560: 
561:       hashCode = Arrays.hashCode(addrs);
562:     }
563: 
564:     @Override
565:     public int hashCode() {
566:       return hashCode;
567:     }
568: 
569:     @Override
570:     public boolean equals(Object other) {
571:       if (this == other) {
572:         return true;
573:       }
574:       if (other == null) {
575:         return false;
576:       }
577: 
578:       if (!(other instanceof Endpoint)) {
579:         return false;
580:       }
581:       Endpoint o = (Endpoint) other;
582:       if (o.hashCode != hashCode || o.addrs.length != addrs.length) {
583:         return false;
584:       }
585: 
586:       return Arrays.equals(o.addrs, this.addrs);
587:     }
588: 
589:     @Override
590:     public String toString() {
591:       return Arrays.toString(addrs);
592:     }
593:   }
594: 
595:   protected static class AcceptResolvedAddressRetVal {
596:     public final boolean valid;
597:     public final List<ChildLbState> removedChildren;
598: 
599:     public AcceptResolvedAddressRetVal(boolean valid, List<ChildLbState> removedChildren) {
600:       this.valid = valid;
601:       this.removedChildren = removedChildren;
602:     }
603:   }
604: }

