277:   private boolean validateAddrList(List<EquivalentAddressGroup> addrList) {
278:     if (addrList.isEmpty()) {
279:       handleNameResolutionError(Status.UNAVAILABLE.withDescription("Ring hash lb error: EDS "
280:           + "resolution was successful, but returned server addresses are empty."));
281:       return false;
282:     }
283: 
284:     String dupAddrString = validateNoDuplicateAddresses(addrList);
285:     if (dupAddrString != null) {
286:       handleNameResolutionError(Status.UNAVAILABLE.withDescription("Ring hash lb error: EDS "
287:           + "resolution was successful, but there were duplicate addresses: " + dupAddrString));
288:       return false;
289:     }
290: 
291:     long totalWeight = 0;
292:     for (EquivalentAddressGroup eag : addrList) {
293:       Long weight = eag.getAttributes().get(InternalXdsAttributes.ATTR_SERVER_WEIGHT);
294: 
295:       if (weight == null) {
296:         weight = 1L;
297:       }
298: 
299:       if (weight < 0) {
300:         handleNameResolutionError(Status.UNAVAILABLE.withDescription(
301:             String.format("Ring hash lb error: EDS resolution was successful, but returned a "
302:                 + "negative weight for %s.", stripAttrs(eag))));
303:         return false;
304:       }
305:       if (weight > UnsignedInteger.MAX_VALUE.longValue()) {
306:         handleNameResolutionError(Status.UNAVAILABLE.withDescription(
307:             String.format("Ring hash lb error: EDS resolution was successful, but returned a weight"
308:                 + " too large to fit in an unsigned int for %s.", stripAttrs(eag))));
309:         return false;
310:       }
311:       totalWeight += weight;
312:     }
313: 
314:     if (totalWeight > UnsignedInteger.MAX_VALUE.longValue()) {
315:       handleNameResolutionError(Status.UNAVAILABLE.withDescription(
316:           String.format(
317:               "Ring hash lb error: EDS resolution was successful, but returned a sum of weights too"
318:               + " large to fit in an unsigned int (%d).", totalWeight)));
319:       return false;
320:     }
321: 
322:     return true;
323:   }
