325:   @Nullable
326:   private String validateNoDuplicateAddresses(List<EquivalentAddressGroup> addrList) {
327:     Set<SocketAddress> addresses = new HashSet<>();
328:     Multiset<String> dups = HashMultiset.create();
329:     for (EquivalentAddressGroup eag : addrList) {
330:       for (SocketAddress address : eag.getAddresses()) {
331:         if (!addresses.add(address)) {
332:           dups.add(address.toString());
333:         }
334:       }
335:     }
336: 
337:     if (!dups.isEmpty()) {
338:       return dups.entrySet().stream()
339:           .map((dup) ->
340:               String.format("Address: %s, count: %d", dup.getElement(), dup.getCount() + 1))
341:           .collect(Collectors.joining("; "));
342:     }
343: 
344:     return null;
345:   }
