347:   private static List<RingEntry> buildRing(
348:       Map<EquivalentAddressGroup, Long> serverWeights, long totalWeight, double scale) {
349:     List<RingEntry> ring = new ArrayList<>();
350:     double currentHashes = 0.0;
351:     double targetHashes = 0.0;
352:     for (Map.Entry<EquivalentAddressGroup, Long> entry : serverWeights.entrySet()) {
353:       Endpoint endpoint = new Endpoint(entry.getKey());
354:       double normalizedWeight = (double) entry.getValue() / totalWeight;
355:       // Per GRFC A61 use the first address for the hash
356:       StringBuilder sb = new StringBuilder(entry.getKey().getAddresses().get(0).toString());
357:       sb.append('_');
358:       int lengthWithoutCounter = sb.length();
359:       targetHashes += scale * normalizedWeight;
360:       long i = 0L;
361:       while (currentHashes < targetHashes) {
362:         sb.append(i);
363:         long hash = hashFunc.hashAsciiString(sb.toString());
364:         ring.add(new RingEntry(hash, endpoint));
365:         i++;
366:         currentHashes++;
367:         sb.setLength(lengthWithoutCounter);
368:       }
369:     }
370:     Collections.sort(ring);
371:     return Collections.unmodifiableList(ring);
372:   }
