382:   private static final class RingHashPicker extends SubchannelPicker {
383:     private final SynchronizationContext syncContext;
384:     private final List<RingEntry> ring;
385:     // Avoid synchronization between pickSubchannel and subchannel's connectivity state change,
386:     // freeze picker's view of subchannel's connectivity state.
387:     // TODO(chengyuanzhang): can be more performance-friendly with
388:     //  IdentityHashMap<Subchannel, ConnectivityStateInfo> and RingEntry contains Subchannel.
389:     private final Map<Endpoint, SubchannelView> pickableSubchannels;  // read-only
390: 
391:     private RingHashPicker(
392:         SynchronizationContext syncContext, List<RingEntry> ring,
393:         ImmutableMap<Object, ChildLbState> subchannels) {
394:       this.syncContext = syncContext;
395:       this.ring = ring;
396:       pickableSubchannels = new HashMap<>(subchannels.size());
397:       for (Map.Entry<Object, ChildLbState> entry : subchannels.entrySet()) {
398:         RingHashChildLbState childLbState = (RingHashChildLbState) entry.getValue();
399:         pickableSubchannels.put((Endpoint)entry.getKey(),
400:             new SubchannelView(childLbState, childLbState.getCurrentState()));
401:       }
402:     }
403: 
404:     // Find the ring entry with hash next to (clockwise) the RPC's hash (binary search).
405:     private int getTargetIndex(Long requestHash) {
406:       if (ring.size() <= 1) {
407:         return 0;
408:       }
409: 
410:       int low = 0;
411:       int high = ring.size() - 1;
412:       int mid = (low + high) / 2;
413:       do {
414:         long midVal = ring.get(mid).hash;
415:         long midValL = mid == 0 ? 0 : ring.get(mid - 1).hash;
416:         if (requestHash <= midVal && requestHash > midValL) {
417:           return mid;
418:         }
419:         if (midVal < requestHash) {
420:           low = mid + 1;
421:         } else {
422:           high =  mid - 1;
423:         }
424:         mid = (low + high) / 2;
425:       } while (mid < ring.size() && low <= high);
426:       return mid;
427:     }
428: 
429:     @Override
430:     public PickResult pickSubchannel(PickSubchannelArgs args) {
431:       Long requestHash = args.getCallOptions().getOption(XdsNameResolver.RPC_HASH_KEY);
432:       if (requestHash == null) {
433:         return PickResult.withError(RPC_HASH_NOT_FOUND);
434:       }
435: 
436:       int targetIndex = getTargetIndex(requestHash);
437: 
438:       // Per gRFC A61, because of sticky-TF with PickFirst's auto reconnect on TF, we ignore
439:       // all TF subchannels and find the first ring entry in READY, CONNECTING or IDLE.  If
440:       // CONNECTING or IDLE we return a pick with no results.  Additionally, if that entry is in
441:       // IDLE, we initiate a connection.
442:       for (int i = 0; i < ring.size(); i++) {
443:         int index = (targetIndex + i) % ring.size();
444:         SubchannelView subchannelView = pickableSubchannels.get(ring.get(index).addrKey);
445:         RingHashChildLbState childLbState = subchannelView.childLbState;
446: 
447:         if (subchannelView.connectivityState  == READY) {
448:           return childLbState.getCurrentPicker().pickSubchannel(args);
449:         }
450: 
451:         // RPCs can be buffered if the next subchannel is pending (per A62). Otherwise, RPCs
452:         // are failed unless there is a READY connection.
453:         if (subchannelView.connectivityState == CONNECTING) {
454:           return PickResult.withNoResult();
455:         }
456: 
457:         if (subchannelView.connectivityState == IDLE || childLbState.isDeactivated()) {
458:           if (childLbState.isDeactivated()) {
459:             childLbState.activate();
460:           } else {
461:             syncContext.execute(() -> childLbState.getLb().requestConnection());
462:           }
463: 
464:           return PickResult.withNoResult(); // Indicates that this should be retried after backoff
465:         }
466:       }
467: 
468:       // return the pick from the original subchannel hit by hash, which is probably an error
469:       RingHashChildLbState originalSubchannel =
470:           pickableSubchannels.get(ring.get(targetIndex).addrKey).childLbState;
471:       return originalSubchannel.getCurrentPicker().pickSubchannel(args);
472:     }
473: 
474:   }
